145: // HandleStop parses the raw JSON payload and handles the Stop event within the execution budget.
146: // It returns a standard JSON object string ("{}") on completion or no-op skip.
147: func HandleStop(ctx context.Context, rawPayload []byte, opts ...HookOption) ([]byte, error) {
148: 	if ctx == nil {
149: 		ctx = context.Background()
150: 	}
151: 	var payload StopPayload
152: 	if len(rawPayload) > 0 && strings.TrimSpace(string(rawPayload)) != "" {
153: 		if err := json.Unmarshal(rawPayload, &payload); err != nil {
154: 			return nil, fmt.Errorf("parsing Stop payload JSON: %w", err)
155: 		}
156: 	}
157: 	payload.Normalize()
158: 
159: 	_, err := HandleStopEvent(ctx, &payload, opts...)
160: 	if err != nil {
161: 		return nil, err
162: 	}
163: 
164: 	return []byte("{}"), nil
165: }
