167: // HandleStopEvent executes the complete Stop hook pipeline:
168: // 1. Enforces execution budget (≤ 200ms)
169: // 2. Evaluates kill-switch checks (REPO_MEMORY_DISABLED, machine config, repo config)
170: // 3. Evaluates REPO_MEMORY_HOUSEKEEPING guard (skipping housekeeping runs)
171: // 4. Evaluates enrolment checks (verifying the workspace is enrolled in registry)
172: // 5. Creates and writes a durable capture spool entry
173: // 6. Performs incremental transcript copying into queue/ with cursor state tracking
174: func HandleStopEvent(ctx context.Context, payload *StopPayload, opts ...HookOption) (*StopResult, error) {
175: 	start := time.Now()
176: 
177: 	opt := HookOptions{
178: 		Timeout: DefaultHookBudget,
179: 	}
180: 	for _, fn := range opts {
181: 		fn(&opt)
182: 	}
183: 
184: 	// 1. Budget enforcement (≤ 200ms)
185: 	budget := opt.Timeout
186: 	if budget <= 0 {
187: 		budget = DefaultHookBudget
188: 	}
189: 	if ctx == nil {
190: 		ctx = context.Background()
191: 	}
192: 	var cancel context.CancelFunc
193: 	if _, hasDeadline := ctx.Deadline(); !hasDeadline {
194: 		ctx, cancel = context.WithTimeout(ctx, budget)
195: 		defer cancel()
196: 	}
197: 
198: 	// 2. Kill-switch check (Step A: REPO_MEMORY_DISABLED env var)
199: 	if os.Getenv("REPO_MEMORY_DISABLED") == "1" || strings.EqualFold(os.Getenv("REPO_MEMORY_DISABLED"), "true") {
200: 		return &StopResult{
201: 			Skipped:  true,
202: 			Reason:   "kill-switch active (REPO_MEMORY_DISABLED)",
203: 			Duration: time.Since(start),
204: 		}, nil
205: 	}
206: 
207: 	// 3. REPO_MEMORY_HOUSEKEEPING guard (Step B: skip housekeeping runs per SPEC §6.2 / E07)
208: 	if os.Getenv("REPO_MEMORY_HOUSEKEEPING") == "1" || strings.EqualFold(os.Getenv("REPO_MEMORY_HOUSEKEEPING"), "true") {
209: 		return &StopResult{
210: 			Skipped:  true,
211: 			Reason:   "housekeeping run skipped (REPO_MEMORY_HOUSEKEEPING)",
212: 			Duration: time.Since(start),
213: 		}, nil
214: 	}
215: 
216: 	dataDir := opt.DataDir
217: 	if dataDir == "" {
218: 		dataDir = config.DataDir()
219: 	}
220: 
221: 	// 2. Kill-switch check (Step C: machine configuration enabled)
222: 	machCfg, err := config.LoadMachineConfig(dataDir)
223: 	if err != nil {
224: 		return nil, fmt.Errorf("loading machine config: %w", err)
225: 	}
226: 	if !machCfg.Enabled {
227: 		return &StopResult{
228: 			Skipped:  true,
229: 			Reason:   "kill-switch active (machine config disabled)",
230: 			Duration: time.Since(start),
231: 		}, nil
232: 	}
233: 
234: 	// Determine candidate workspace
235: 	workspace := opt.WorkspaceOverride
236: 	if workspace == "" && len(payload.WorkspacePaths) > 0 && payload.WorkspacePaths[0] != "" {
237: 		workspace = payload.WorkspacePaths[0]
238: 	}
239: 	if workspace == "" && payload.TranscriptPath != "" {
240: 		if root, err := gitops.FindRepoRoot(filepath.Dir(payload.TranscriptPath)); err == nil {
241: 			workspace = root
242: 		}
243: 	}
244: 	var convSummary *ConversationSummary
245: 	if (workspace == "" || payload.ParentConversationID == "") && payload.ConversationID != "" && (opt.AppDBPath != "" || opt.CliDBPath != "") {
246: 		var attrOpts []AttributionOption
247: 		if opt.AppDBPath != "" {
248: 			attrOpts = append(attrOpts, WithAppDBPath(opt.AppDBPath))
249: 		}
250: 		if opt.CliDBPath != "" {
251: 			attrOpts = append(attrOpts, WithCliDBPath(opt.CliDBPath))
252: 		}
253: 		convSummary, _ = LookupConversationSummary(payload.ConversationID, attrOpts...)
254: 		if workspace == "" && convSummary != nil && len(convSummary.WorkspacePaths) > 0 {
255: 			workspace = convSummary.WorkspacePaths[0]
256: 		}
257: 	}
258: 	if workspace == "" {
259: 		if wd, err := os.Getwd(); err == nil {
260: 			workspace = wd
261: 		}
262: 	}
263: 
264: 	// Additional housekeeping path guard: directory matching runs/<repo-id>
265: 	if isHousekeepingPath(workspace) {
266: 		return &StopResult{
267: 			Skipped:  true,
268: 			Reason:   "housekeeping directory skipped (runs/ path)",
269: 			Duration: time.Since(start),
270: 		}, nil
271: 	}
272: 
273: 	// 4. Enrolment check (Step D: verify repository enrolment in registry.json)
274: 	entry, found, err := config.FindRegistryEntry(dataDir, workspace)
275: 	if err != nil {
276: 		return nil, fmt.Errorf("querying registry: %w", err)
277: 	}
278: 	if !found || entry == nil {
279: 		return &StopResult{
280: 			Skipped:  true,
281: 			Reason:   "workspace not enrolled in registry",
282: 			Duration: time.Since(start),
283: 		}, nil
284: 	}
285: 
286: 	// 2. Kill-switch check (Step E: repository config enabled)
287: 	repoCfg, err := config.LoadRepoConfig(entry.RootPath)
288: 	if err != nil {
289: 		return nil, fmt.Errorf("loading repo config: %w", err)
290: 	}
291: 	if !repoCfg.IsEnabled() {
292: 		return &StopResult{
293: 			Skipped:  true,
294: 			Reason:   "kill-switch active (repo config disabled)",
295: 			Duration: time.Since(start),
296: 		}, nil
297: 	}
298: 
299: 	repoID := entry.RepoID
300: 	if repoID == "" {
301: 		repoID, err = gitops.GenerateRepoID(entry.RootPath)
302: 		if err != nil {
303: 			return nil, fmt.Errorf("generating repo ID: %w", err)
304: 		}
305: 	}
306: 	repoRoot := entry.RootPath
307: 
308: 	// Ensure destination directory structure exists under <data-dir>/<repo-id>/
309: 	if err := config.EnsureDataDirLayout(dataDir, repoID); err != nil {
310: 		return nil, fmt.Errorf("ensuring data dir layout: %w", err)
311: 	}
312: 
313: 	// Query Git branch and HEAD commit (bounded by 50ms context timeout to preserve budget)
314: 	gitCtx, gitCancel := context.WithTimeout(ctx, 50*time.Millisecond)
315: 	branch, _ := gitops.GetCurrentBranchWithContext(gitCtx, repoRoot)
316: 	head, _ := gitops.GetHeadCommitWithContext(gitCtx, repoRoot)
317: 	gitCancel()
318: 
319: 	convID := payload.ConversationID
320: 	if convID == "" {
321: 		return &StopResult{
322: 			Skipped:  true,
323: 			Reason:   "conversation ID empty; no session to capture",
324: 			RepoID:   repoID,
325: 			RepoRoot: repoRoot,
326: 			Duration: time.Since(start),
327: 		}, nil
328: 	}
329: 
330: 	// Resolve transcript source path
331: 	transcriptPath := payload.TranscriptPath
332: 	if transcriptPath == "" {
333: 		transcriptPath = findBrainTranscript(convID)
334: 	}
335: 
336: 	// 5. Spool entry creation (using packages from WO1)
337: 	spoolDir := filepath.Join(dataDir, repoID, "spool")
338: 	captureEntry := spool.NewCaptureEntry("antigravity", convID, transcriptPath, repoRoot, branch, head)
339: 	parentConvID := opt.ParentConversationID
340: 	if parentConvID == "" {
341: 		parentConvID = payload.ParentConversationID
342: 	}
343: 	if parentConvID == "" && convSummary != nil {
344: 		parentConvID = convSummary.ParentConversationID
345: 	}
346: 	captureEntry.ParentConversationID = parentConvID
347: 	spoolPath, err := spool.Write(spoolDir, captureEntry)
348: 	if err != nil {
349: 		return nil, fmt.Errorf("writing capture spool entry: %w", err)
350: 	}
351: 
352: 	// 6. Incremental copy (using packages from WO1)
353: 	queueDir := filepath.Join(dataDir, repoID, "queue")
354: 	stateDir := filepath.Join(dataDir, repoID, "state")
355: 
356: 	var copyResult *spool.CopyResult
357: 	if transcriptPath != "" {
358: 		if _, err := os.Stat(transcriptPath); err == nil {
359: 			copyResult, err = spool.CopyTranscriptIncremental(convID, transcriptPath, queueDir, stateDir)
360: 			if err != nil {
361: 				return nil, fmt.Errorf("copying transcript incrementally: %w", err)
362: 			}
363: 		}
364: 	}
365: 
366: 	duration := time.Since(start)
367: 	return &StopResult{
368: 		Skipped:              false,
369: 		ConversationID:       convID,
370: 		ParentConversationID: parentConvID,
371: 		RepoID:               repoID,
372: 		RepoRoot:             repoRoot,
